def STEP(view, state):
    if state is None:
        state = {"step": 0}
    state["step"] = state.get("step", 0) + 1
    if not view.get("observations"):
        action = {"kind": "diagnose", "target": "task", "inputs": {"task_content": view.get("task_content")}, "evidence_refs": [], "requested_resources": {}}
        return {"action": action, "state": state}
    action = {"kind": "stop", "target": "policy", "inputs": {}, "evidence_refs": [], "requested_resources": {}}
    return {"action": action, "state": state}

